import React from "react";

// Allectricity mark: a circuit-trace "A" standing on a ground symbol. Same geometry as app/public/brand/*.svg
// (generated by scripts/brand_mark.py); keep both in step. Below 40 px the strokes get heavier to stay legible. tone="light" for light surfaces, "dark" for the landing.
const TONES = {
  light: { ink: "#12332c", trace: "#288778", accent: "#3ea894" },
  dark: { ink: "#e9fbf5", trace: "#3ea894", accent: "#9ef0d8" },
};

export function BrandMark({ size = 32, tone = "light", className = "", title }) {
  const { ink, trace, accent } = TONES[tone] || TONES.light;
  return (
    <svg className={`brand-mark-svg ${className}`} width={size} height={size} viewBox="0 0 64 64" role={title ? "img" : undefined}
      aria-hidden={title ? undefined : true} aria-label={title} focusable="false">
      <g fill="none" strokeWidth={size < 40 ? 4.8 : 3.6} strokeLinecap="butt" strokeLinejoin="miter">
        <path d="M15.43 40 L29.57 6 H36 L38.99 12.97" stroke={trace} />
        <path d="M40.75 17.07 L43.38 23.22" stroke={accent} />
        <path d="M45.14 27.32 L50.59 40.03" stroke={trace} />
        <path d="M5 47 H20 L32 19 L44 47 H59 M24.71 36 H39.29" stroke={ink} />
        <path d="M45 53 H57 M48 59 H54" stroke={accent} />
      </g>
    </svg>
  );
}
